fn trunc_len(n: usize, m: usize) -> usize {
    if m == 0 {
        // no truncation requested
        n
    } else if n > m {
        // can drop `m` elements and still have at least one left
        n - m
    } else {
        // m >= n, so we truncate down to a single element
        1
    }
}

fn legder(c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let n = c.len();
    let m_usize = m as usize;
    let new_len = trunc_len(n, m_usize);

    // We own `c`, so we can just truncate it in place.
    let mut result = c;
    result.truncate(new_len);
    result
}

