    #[test]
    fn test_legder() {
        let v = vec![1.0, 2.0, 3.0, 4.0];
        // m = 0: unchanged
        assert_eq!(legder(v.clone(), 0, 42.0), vec![1.0, 2.0, 3.0, 4.0]);
        // m = 2: drop first 2 → keep first 2 of the original
        assert_eq!(legder(v.clone(), 2, 0.0), vec![1.0, 2.0]);
        // m = length: returns only the first element
        assert_eq!(legder(v.clone(), 4, 1.0), vec![1.0]);
        // m > length: still returns only the first element
        assert_eq!(legder(v.clone(), 6, -1.0), vec![1.0]);
    }
